const {chromium}=require('playwright');(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:900,height:900}});p.on('pageerror',e=>console.log('ERR',e.message));await p.goto('file:///home/claude/v10/shape-system.html');await p.waitForTimeout(4500);await p.screenshot({path:'full.png',fullPage:true});const t=await p.$('#tiny');await t.screenshot({path:'tiny.png'});
const q=await b.newPage({viewport:{width:390,height:800}});await q.goto('file:///home/claude/v10/shape-system.html');await q.waitForTimeout(500);console.log('sw',await q.evaluate(()=>document.documentElement.scrollWidth));await b.close();})();
